namespace RonSijm.FluidHumidifier.Factories.S3;

public class InnerJobJobOperationFactory(Action<Humidifier.S3.JobTypes.JobOperation> factoryAction = null) : SubResourceFactory<Humidifier.S3.JobTypes.JobOperation>
{

    internal InnerJobS3ComputeObjectChecksumOperationFactory S3ComputeObjectChecksumFactory { get; set; }

    internal InnerJobS3SetObjectLegalHoldOperationFactory S3PutObjectLegalHoldFactory { get; set; }

    internal InnerJobS3CopyObjectOperationFactory S3PutObjectCopyFactory { get; set; }

    internal InnerJobS3SetObjectAclOperationFactory S3PutObjectAclFactory { get; set; }

    internal InnerJobLambdaInvokeOperationFactory LambdaInvokeFactory { get; set; }

    internal InnerJobS3SetObjectRetentionOperationFactory S3PutObjectRetentionFactory { get; set; }

    internal InnerJobS3UpdateObjectEncryptionOperationFactory S3UpdateObjectEncryptionFactory { get; set; }

    internal InnerJobS3InitiateRestoreObjectOperationFactory S3InitiateRestoreObjectFactory { get; set; }

    internal InnerJobS3SetObjectTaggingOperationFactory S3PutObjectTaggingFactory { get; set; }

    protected override Humidifier.S3.JobTypes.JobOperation Create()
    {
        var jobOperationResult = CreateJobOperation();
        factoryAction?.Invoke(jobOperationResult);

        return jobOperationResult;
    }

    private Humidifier.S3.JobTypes.JobOperation CreateJobOperation()
    {
        var jobOperationResult = new Humidifier.S3.JobTypes.JobOperation();

        return jobOperationResult;
    }
    public override void CreateChildren(Humidifier.S3.JobTypes.JobOperation result)
    {
        base.CreateChildren(result);

        result.S3ComputeObjectChecksum ??= S3ComputeObjectChecksumFactory?.Build();
        result.S3PutObjectLegalHold ??= S3PutObjectLegalHoldFactory?.Build();
        result.S3PutObjectCopy ??= S3PutObjectCopyFactory?.Build();
        result.S3PutObjectAcl ??= S3PutObjectAclFactory?.Build();
        result.LambdaInvoke ??= LambdaInvokeFactory?.Build();
        result.S3PutObjectRetention ??= S3PutObjectRetentionFactory?.Build();
        result.S3UpdateObjectEncryption ??= S3UpdateObjectEncryptionFactory?.Build();
        result.S3InitiateRestoreObject ??= S3InitiateRestoreObjectFactory?.Build();
        result.S3PutObjectTagging ??= S3PutObjectTaggingFactory?.Build();
    }

} // End Of Class

